<style id="wp-custom-css">
/*Remove Highlight Color on Click */
* {
  -webkit-tap-highlight-color: transparent;
}

/* Set text highlight color to #26AFAF */
::-moz-selection {
    background-color: #704B4170;
    color: #fff; /* Set the text color inside the selection for Firefox */
}

::selection {
    background-color: #704B4170;
    color: #fff; /* Set the text color inside the selection for other browsers */
}

.scroll-offset {
    padding-top: 30vh; /* Adjust this value to suit your layout */
    margin-top: -30vh; /* Adjust this value to be the negative of padding-top */
}

html {
    scroll-behavior: smooth;
}

*:focus,
*:active {
    outline: none;
}

/* Remove default browser focus outline for all focusable elements */
:focus {
    outline: none;
}

/* Hide scrollbar for all browsers */
html {
    overflow: -moz-scrollbars-none; /* Firefox */
    -ms-overflow-style: none; /* Internet Explorer and Edge */
}

body {
    overflow-y: scroll; /* Always show vertical scrollbar */
}

/* Hide scrollbar for WebKit browsers (Chrome, Safari) */
body::-webkit-scrollbar {
    display: none; /* Hides scrollbar */
}

/* Allow scrolling */
body {
    overflow-y: scroll; /* Enable vertical scrolling */
}

html {
  max-width: 100%;
}

body {
  max-width: 100%;
  position: relative;
}

/* Safer horizontal containment without breaking scroll-lock / pin animations */
#page,
.site,
.elementor,
.elementor-location-body {
  width: 100%;
  max-width: 100%;
  overflow-x: clip;
}

@supports not (overflow: clip) {
  #page,
  .site,
  .elementor,
  .elementor-location-body {
    overflow-x: hidden;
  }
}

img,
video,
svg,
canvas {
  max-width: 100%;
}
</style>
<style>

/* =========================
KHUFU'S ABOUT HERO
========================= */

@font-face{
  font-family:"IvyOraDisplay";
  src:url("/assets/images/IvyOraDisplay-Light.woff2") format("woff2");
  font-weight:300;
  font-style:normal;
  font-display:swap;
}

@font-face{
  font-family:"GoldenHopes";
  src:url("/assets/images/GoldenHopes.woff2") format("woff2");
  font-weight:400;
  font-style:normal;
  font-display:swap;
}

@import url("https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@300;400&display=swap");


.kh-about-hero,
.kh-about-hero *{
  box-sizing:border-box;
}

.kh-about-hero{
  position:relative;
  width:100%;
  height:100svh;
  display:flex;
  align-items:flex-end;
  overflow:hidden;
  isolation:isolate;

  background:
  linear-gradient(
    180deg,
    rgba(88,74,56,.055) 0%,
    rgba(88,74,56,.20) 32%,
    rgba(88,74,56,.44) 60%,
    rgba(88,74,56,.76) 86%,
    rgba(88,74,56,.88) 100%
  ),
  url("/assets/images/About-Landing-Image.webp")
  center center / cover no-repeat;
}


/* background monumental word */

.kh-about-hero::after{
  content:"KHUFU'S";
  position:absolute;
  right:-10px;
  bottom:-10px;
  font-family:"IvyOraDisplay",serif;
  font-size:160px;
  line-height:.85;
  letter-spacing:.05em;
  color:rgba(247,243,238,.04);
  pointer-events:none;
}


/* =========================
LAYOUT
========================= */

.kh-about-inner{
  width:100%;
  padding:60px;
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(260px,340px);
  gap:40px;
  align-items:end;
  position:relative;
  z-index:2;
}


/* =========================
LEFT COLUMN
========================= */

.kh-about-copy{
  max-width:720px;
}

.kh-about-kicker{
  margin-bottom:16px;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:11px;
  letter-spacing:.26em;
  text-transform:uppercase;
  color:rgba(247,243,238,.65);
}

.kh-about-title{
  margin:0;
  font-family:"IvyOraDisplay",serif;
  font-weight:300;
  font-size:56px;
  line-height:1.05;
  letter-spacing:.01em;
  color:#F7F3EE;
  text-transform:uppercase;
  position:relative;
}


/* Golden Hopes script overlap */

.kh-about-script{
  position:absolute;
  left:0;
  bottom:-18px;
  font-family:"GoldenHopes",cursive;
  font-size:30px;
  color:#F2E4C7;
  letter-spacing:.04em;
  transform:rotate(-2deg);
  text-transform:capitalize;
  pointer-events:none;
}


/* paragraph */

.kh-about-lead{
  margin-top:36px;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:14px;
  line-height:1.8;
  color:rgba(247,243,238,.75);
  font-weight:300;
  max-width:520px;
}


/* scroll */

.kh-scroll{
  margin-top:28px;
  display:flex;
  align-items:center;
  gap:10px;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:10px;
  letter-spacing:.26em;
  text-transform:uppercase;
  color:rgba(247,243,238,.62);
}

.kh-scroll-line{
  width:46px;
  height:1px;
  background:rgba(247,243,238,.35);
}


/* =========================
RIGHT COLUMN
========================= */

.kh-about-side{
  width:100%;
  max-width:300px;
  margin-left:auto;
  border-top:1px solid rgba(255,255,255,.14);
  padding-top:16px;
  text-align:right;
}

.kh-about-side p{
  margin:0;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:13px;
  line-height:1.75;
  color:rgba(247,243,238,.65);
  font-weight:300;
}


/* =========================
ANIMATION
========================= */

.kh-reveal{
  opacity:0;
  transform:translateY(30px);
  transition:
    opacity .9s cubic-bezier(.22,1,.36,1),
    transform .9s cubic-bezier(.22,1,.36,1);
}

.kh-reveal.show{
  opacity:1;
  transform:translateY(0);
}


/* =========================
RESPONSIVE
========================= */

@media(max-width:900px){

  .kh-about-inner{
    grid-template-columns:1fr;
    padding:30px 30px;
    gap:24px;
  }

  .kh-about-side{
    display:none;
  }

  .kh-about-kicker{
    font-size:9px;
    letter-spacing:.22em;
  }

  .kh-about-title{
    font-size:30px;
    padding-bottom:10px;
  }

  .kh-about-script{
    bottom:-22px;
  }

  .kh-about-lead{
    font-size:12px;
    line-height:1.6;
  }

  .kh-about-hero::after{
    font-size:88px;
    right:-6px;
    bottom:-4px;
    display:none !important;
  }
}

</style>
<style>

@font-face{
  font-family:"IvyOraDisplay";
  src:url("/assets/images/IvyOraDisplay-Light.woff2") format("woff2");
  font-weight:300;
  font-style:normal;
  font-display:swap;
}

@font-face{
  font-family:"GoldenHopes";
  src:url("/assets/images/GoldenHopes.woff2") format("woff2");
  font-weight:400;
  font-style:normal;
  font-display:swap;
}

@import url("https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@300;400;500&display=swap");

/* =========================
SHARED
========================= */

.kh-origin-desktop,
.kh-origin-desktop *,
.kh-origin-mobile,
.kh-origin-mobile *{
  box-sizing:border-box;
}

.kh-origin-desktop,
.kh-origin-mobile{
  --kh-bg:#F6F1EA;
  --kh-bg-soft:#F1E9DF;
  --kh-card:rgba(250,247,242,.90);
  --kh-card-soft:rgba(244,236,226,.82);
  --kh-text:#3F2C1F;
  --kh-text-soft:rgba(63,44,31,.76);
  --kh-text-muted:rgba(63,44,31,.60);
  --kh-brown:#3F2C1F;
  --kh-brown-soft:#6A4C36;
  --kh-line:rgba(63,44,31,.12);
  --kh-line-soft:rgba(63,44,31,.08);
}

/* =========================
DESKTOP
UNCHANGED
========================= */

.kh-origin-copy::before{
  content:"";
  position:absolute;
  top:0;
  left:0;
  width:100px;
  height:100px;
  background-color:#6A4C36;
  opacity:0;
  -webkit-mask:url("/assets/images/Khufus-Pattern.svg") no-repeat left top / contain;
  mask:url("/assets/images/Khufus-Pattern.svg") no-repeat left top / contain;
  pointer-events:none;
  z-index:3;
  transform:translateY(36px);
  filter:blur(2px);
  transition:
    transform 1s cubic-bezier(.22,1,.36,1),
    opacity 1s cubic-bezier(.22,1,.36,1),
    filter 1s cubic-bezier(.22,1,.36,1);
  will-change:transform, opacity, filter;
}

#khOriginDesktop.show .kh-origin-copy::before{
  opacity:.28;
  transform:none;
  filter:blur(0);
}

.kh-origin-desktop{
  --kh-origin-main-width:380px;
  --kh-origin-mini-width:188px;
  width:100%;
  height:100vh;
  min-height:100vh;
  padding:60px;
  position:relative;
  overflow:hidden;
  background:linear-gradient(180deg,#F6F1EA 0%,#F1E9DF 100%);
}

.kh-origin-desktop::before{
  content:"";
  position:absolute;
  inset:0;
  background:
    radial-gradient(circle at 15% 20%, rgba(92,71,43,.05), transparent 28%),
    linear-gradient(90deg, rgba(255,255,255,.18), transparent 18%);
  pointer-events:none;
}

.kh-origin-wrap{
  width:100%;
  height:100%;
  position:relative;
  z-index:2;
}

.kh-origin-grid{
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(360px,520px);
  gap:80px;
  height:100%;
  align-items:stretch;
}

.kh-origin-copy{
  position:relative;
  max-width:560px;
  height:100%;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  padding:56px 0 8px;
}

.kh-origin-copy-main{
  display:flex;
  flex-direction:column;
  justify-content:center;
  flex:1;
  transform:translateY(18px);
}

.kh-origin-copy-top{
  position:relative;
  display:flex;
  flex-direction:column;
  align-items:flex-start;
}

.kh-origin-copy-bottom{
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  justify-content:flex-end;
  padding-bottom:0;
  margin-bottom:-30px;
}

.kh-origin-number{
  position:absolute;
  top:-55px;
  left:0;
  font-family:"IvyOraDisplay", serif;
  font-weight:300;
  font-size:clamp(78px,8vw,146px);
  color:rgba(92,71,43,.08);
  line-height:.8;
  letter-spacing:.02em;
  pointer-events:none;
  user-select:none;
  z-index:0;
}

.kh-origin-kicker{
  position:relative;
  z-index:1;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:10px;
  letter-spacing:.28em;
  text-transform:uppercase;
  color:#6A4C36;
  font-weight:400;
  margin:0 0 12px;
}

.kh-origin-title{
  position:relative;
  z-index:1;
  margin:0;
  font-family:"IvyOraDisplay", serif;
  font-weight:300;
  font-size:clamp(28px,2.2vw,40px);
  line-height:.98;
  text-transform:uppercase;
  color:#3F2C1F;
  max-width:460px;
}

.kh-origin-script{
  display:block;
  margin-top:-4px;
  margin-left:88px;
  font-family:"GoldenHopes", cursive;
  font-size:clamp(22px,1.7vw,30px);
  line-height:1;
  letter-spacing:.03em;
  text-transform:capitalize;
  color:#6A4C36;
  transform:rotate(-2deg);
}

.kh-origin-text{
  margin:14px 0 0;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:13px;
  line-height:1.78;
  color:rgba(63,44,31,.76);
  max-width:470px;
}

.kh-origin-divider{
  width:84px;
  height:1px;
  background:rgba(63,44,31,.14);
  margin:0 0 12px;
}

.kh-origin-note{
  margin:0;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:11px;
