    radial-gradient(circle at 70% 20%, rgba(255,255,255,.05), transparent 28%);
  pointer-events:none;
}

.kh-arch-mini{
  position:absolute;
  right:calc(100% - var(--kh-arch-main-width) - (var(--kh-arch-mini-width) / 2));
