  font-family:"GoldenHopes";
  src:url("/assets/images/GoldenHopes.woff2") format("woff2");
  font-weight:400;
  font-style:normal;
  font-display:swap;
}

@import url("https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@300;400;500&display=swap");

.kh-final-sec,
.kh-final-sec *{
  box-sizing:border-box;
}

.kh-final-sec{
  --kh-final-main-width:380px;
  --kh-final-mini-width:210px;
  width:100%;
  min-height:100vh;
  padding:60px;
  position:relative;
  overflow:hidden;
  isolation:isolate;
  background:#111;
}

.kh-final-sec::before{
  content:"";
  position:absolute;
  inset:0;
  background:
    linear-gradient(180deg, rgba(0,0,0,.42) 0%, rgba(0,0,0,.54) 34%, rgba(0,0,0,.76) 100%),
    linear-gradient(180deg, rgba(255,255,255,.03) 0%, rgba(0,0,0,.12) 100%),
    radial-gradient(circle at 14% 20%, rgba(255,255,255,.06), transparent 24%),
    radial-gradient(circle at 82% 18%, rgba(255,255,255,.04), transparent 22%),
    linear-gradient(90deg, rgba(255,255,255,.05), transparent 18%),
    url("/assets/images/About-Last-Section.webp") center center / cover no-repeat;
  filter:grayscale(1) saturate(.25);
  pointer-events:none;
  z-index:0;
}

.kh-final-sec::after{
  content:"KHUFUS";
  position:absolute;
  right:-12px;
  bottom:-14px;
  font-family:"IvyOraDisplay", serif;
  font-size:clamp(86px,13vw,220px);
  font-weight:300;
  line-height:.82;
  letter-spacing:.03em;
  text-transform:uppercase;
  color:rgba(250,247,242,.05);
  pointer-events:none;
  user-select:none;
  z-index:0;
}

.kh-final-wrap{
  width:100%;
  min-height:calc(100vh - 120px);
  position:relative;
  z-index:2;
}

.kh-final-grid{
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(340px,520px);
  gap:80px;
  min-height:calc(100vh - 120px);
  align-items:stretch;
}

/* =========================
LEFT COPY
========================= */

.kh-final-copy{
  position:relative;
  max-width:620px;
  height:100%;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  padding:56px 0 8px;
}

.kh-final-copy-main{
  display:flex;
  flex-direction:column;
  justify-content:center;
  flex:1;
  transform:translateY(10px);
}

.kh-final-copy-top{
  position:relative;
  display:flex;
  flex-direction:column;
  align-items:flex-start;
}

.kh-final-copy-bottom{
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  justify-content:flex-end;
  padding-bottom:0;
  margin-bottom:-18px;
}

.kh-final-number{
  position:absolute;
  top:-55px;
  left:0;
  font-family:"IvyOraDisplay", serif;
  font-weight:300;
  font-size:clamp(78px,8vw,146px);
  color:rgba(250,247,242,.12);
  line-height:.8;
  letter-spacing:.02em;
  pointer-events:none;
  user-select:none;
  z-index:0;
}

.kh-final-kicker{
  position:relative;
  z-index:1;
  margin:0 0 12px;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:10px;
  letter-spacing:.28em;
  text-transform:uppercase;
  color:rgba(250,247,242,.82);
  font-weight:400;
}

.kh-final-title{
  position:relative;
  z-index:1;
  margin:0;
  max-width:700px;
  font-family:"IvyOraDisplay", serif;
  font-weight:300;
  font-size:clamp(34px,3.6vw,62px);
  line-height:.94;
  text-transform:uppercase;
  color:#FAF7F2;
}

.kh-final-script{
  display:block;
  margin-top:-2px;
  margin-left:110px;
  font-family:"GoldenHopes", cursive;
  font-size:clamp(24px,1.9vw,34px);
  line-height:1;
  letter-spacing:.03em;
  text-transform:capitalize;
  color:rgba(235,218,196,.96);
  transform:rotate(-2deg);
}

.kh-final-text{
  margin:18px 0 0;
  max-width:540px;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:13px;
  line-height:1.82;
  color:rgba(250,247,242,.80);
}

.kh-final-divider{
  width:84px;
  height:1px;
  background:rgba(255,255,255,.18);
  margin:0 0 16px;
}

.kh-final-note{
  margin:0;
  max-width:420px;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:11px;
  line-height:1.72;
  color:rgba(250,247,242,.64);
}

.kh-final-actions{
  margin-top:28px;
  display:flex;
  flex-wrap:wrap;
  gap:12px;
}

.kh-final-btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:12px;
  min-width:210px;
  padding:16px 24px;
  border:1px solid rgba(255,255,255,.16);
  background:rgba(255,255,255,.08);
  backdrop-filter:blur(10px);
  -webkit-backdrop-filter:blur(10px);
  text-decoration:none !important;
  text-transform:uppercase;
  letter-spacing:.22em;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:11px;
  font-weight:400;
  color:#FAF7F2;
  transition:
    transform .35s ease,
    background .35s ease,
    border-color .35s ease,
    color .35s ease;
}

.kh-final-btn:hover{
  transform:translateY(-2px);
  background:rgba(255,255,255,.14);
  border-color:rgba(255,255,255,.24);
  color:#FAF7F2;
}

.kh-final-btn svg{
  width:16px;
  height:16px;
  transition:transform .35s ease;
}

.kh-final-btn:hover svg{
  transform:translateX(4px);
}

.kh-final-btn--ghost{
  background:transparent;
  color:rgba(250,247,242,.88);
}

.kh-final-btn--ghost:hover{
  background:rgba(255,255,255,.06);
  color:#FAF7F2;
}

/* =========================
RIGHT VISUAL STACK
========================= */

.kh-final-visual{
  position:relative;
  height:100%;
}

.kh-final-main{
  position:absolute;
  right:0;
  bottom:0;
  width:var(--kh-final-main-width);
  height:100%;
  border-radius:220px 220px 0 0;
  overflow:hidden;
  background:
    linear-gradient(180deg, rgba(24,18,12,.10) 0%, rgba(24,18,12,.30) 100%),
    url("/assets/images/Khufus-Food.webp") center/cover no-repeat;
  box-shadow:0 28px 60px rgba(0,0,0,.18);
}

.kh-final-main::before{
  content:"";
  position:absolute;
  inset:0;
  background:
    linear-gradient(180deg, rgba(246,241,234,.02) 0%, rgba(246,241,234,.06) 100%),
    radial-gradient(circle at 72% 20%, rgba(255,255,255,.06), transparent 28%);
  pointer-events:none;
}

.kh-final-mini{
  position:absolute;
  left:calc(100% - var(--kh-final-main-width) - (var(--kh-final-mini-width) / 2));
  top:54px;
  width:var(--kh-final-mini-width);
  height:250px;
  border-radius:140px 140px 0 0;
  overflow:hidden;
  background:linear-gradient(180deg, rgba(250,247,242,.16) 0%, rgba(250,247,242,.06) 100%);
  backdrop-filter:blur(2px);
  -webkit-backdrop-filter:blur(2px);
  box-shadow:0 16px 40px rgba(0,0,0,.10);
  border:1px solid rgba(255,255,255,.10);
}

.kh-final-mini::before{
  content:"";
  position:absolute;
  inset:0;
  background-color:rgba(255,255,255,.5);
  -webkit-mask:url("/assets/images/Tree-Var-Icon.svg") 
    no-repeat calc(50% + 0px) calc(50% + 4px) / 70% auto;
  mask:url("/assets/images/Tree-Var-Icon.svg") 
    no-repeat calc(50% + 0px) calc(50% + 4px) / 70% auto;
  transform:scaleX(-1);
  pointer-events:none;
  z-index:2;
}

.kh-final-card{
  position:absolute;
  left:46px;
  bottom:0;
  width:320px;
  background:rgba(250,247,242,.84);
  backdrop-filter:blur(12px);
  -webkit-backdrop-filter:blur(12px);
  padding:22px;
  border:1px solid rgba(63,44,31,.08);
  box-shadow:0 22px 44px rgba(0,0,0,.10);
}

.kh-final-card-label{
  margin-bottom:10px;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:10px;
  letter-spacing:.24em;
  text-transform:uppercase;
  color:#6A4C36;
  font-weight:500;
}

.kh-final-card p{
  margin:0;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:12px;
  line-height:1.76;
  color:rgba(63,44,31,.74);
  font-weight:300;
}

/* =========================
ANIMATION
========================= */

.kh-final-animate{
  opacity:0;
  transform:translateY(36px);
  transition:
    transform 1s cubic-bezier(.22,1,.36,1),
    opacity 1s cubic-bezier(.22,1,.36,1),
    filter 1s cubic-bezier(.22,1,.36,1);
  filter:blur(2px);
  will-change:transform, opacity, filter;
}

.kh-final-animate.show{
  opacity:1;
  transform:none;
  filter:blur(0);
}

.kh-final-delay1{transition-delay:.10s}
.kh-final-delay2{transition-delay:.18s}
.kh-final-delay3{transition-delay:.26s}
.kh-final-delay4{transition-delay:.34s}

@media(min-width:1400px){
  .kh-final-sec{
    --kh-final-main-width:460px;
  }

  .kh-final-grid{
    grid-template-columns:minmax(0,1.08fr) minmax(460px,640px);
    gap:64px;
  }

  .kh-final-copy{
    max-width:700px;
  }

  .kh-final-title{
    max-width:760px;
  }

  .kh-final-text{
    max-width:620px;
  }

  .kh-final-note{
    max-width:560px;
  }
}

/* =========================
RESPONSIVE
========================= */

@media(max-width:1100px){

  .kh-final-sec{
    min-height:100vh;
    padding:60px 28px;
  }

  .kh-final-wrap,
  .kh-final-grid{
    min-height:auto;
  }

  .kh-final-grid{
    grid-template-columns:1fr;
    gap:46px;
  }

  .kh-final-copy{
    height:auto;
    padding:0;
    justify-content:flex-start;
  }

  .kh-final-copy-main{
    transform:none;
  }

  .kh-final-copy-bottom{
    padding-top:18px;
    margin-bottom:0;
  }

  .kh-final-number{
    top:-22px;
    left:0;
  }

  .kh-final-visual{
    height:620px;
  }

  .kh-final-main{
    width:var(--kh-final-main-width);
    height:100%;
  }

  .kh-final-card{
    left:46px;
  }

  .kh-final-script{
    margin-left:82px;
  }
}

@media(max-width:767px){

  .kh-final-sec{
    min-height:100vh;
    padding:30px;
  }

  .kh-final-sec::after{
    content:none;
  }

  .kh-final-grid{
    grid-template-columns:1fr !important;
    gap:0 !important;
    min-height:auto;
  }

  .kh-final-wrap{
    min-height:calc(100vh - 60px);
  }

  .kh-final-visual{
    display:none !important;
  }

  .kh-final-copy{
    max-width:100% !important;
    min-height:calc(100vh - 60px);
    padding:0;
    justify-content:center;
  }

  .kh-final-copy-main{
    transform:none;
    justify-content:center;
    flex:1 1 auto;
  }

  .kh-final-copy-top{
    width:100%;
    max-width:320px;
  }

  .kh-final-copy-bottom{
    width:100%;
    max-width:320px;
    margin-bottom:0;
    padding-top:33px;
  }

  .kh-final-number{
    top:-18px;
    left:0;
    font-size:clamp(58px,18vw,92px);
  }

  .kh-final-title{
    font-size:clamp(30px,9vw,42px);
    line-height:.98;
  }

  .kh-final-script{
    margin-top:-2px;
    margin-left:42px;
    font-size:clamp(20px,6vw,26px);
  }

  .kh-final-text{
    margin-top:14px;
    font-size:13px;
    line-height:1.76;
  }

  .kh-final-actions{
    margin-top:16px;
    gap:10px;
    width:100%;
  }

  .kh-final-btn{
    width:100%;
    min-width:100%;
    padding:16px 18px;
    font-size:11px;
  }

  .kh-final-divider{
    margin-bottom:12px;
  }

  .kh-final-note{
    font-size:11px;
    line-height:1.70;
  }

  .kh-final-card p{
    font-size:12px;
    line-height:1.74;
  }
}

</style>
