/* ===== Standalone Bricolage Button ===== */
.mnq-landing-reserve-btn {
    position: relative;
    display: inline-block;

    font-family: "Bricolage Grotesque", sans-serif;
    font-size: 14px;
    font-weight: 300;
    text-transform: uppercase;
    letter-spacing: 0.08em;

    color: #ffffff;
    text-decoration: none !important;

    cursor: pointer;
    transition:
      opacity 0.3s ease-in-out,
      transform 0.35s ease-in-out;

    will-change: opacity, transform;
}

/* Underline */
.mnq-landing-reserve-btn::after {
    content: '';
    position: absolute;
    left: 0;
    bottom: -3px;
    width: 100%;
    height: 1px;
    background-color: rgba(255,255,255,0.8);
    transition: width 0.3s ease-in-out, opacity 0.3s ease-in-out;
}

/* Hover */
.mnq-landing-reserve-btn:hover::after,
.mnq-landing-reserve-btn:focus::after {
    width: 0;
    opacity: 0;
}

.mnq-landing-reserve-btn:hover,
.mnq-landing-reserve-btn:focus {
    opacity: 0.3;
    color: #ffffff;
}

.mnq-landing-reserve-btn:focus {
    outline: none;
}

/* Scroll state */
.mnq-landing-reserve-btn.is-hidden-on-scroll {
    opacity: 0;
    transform: translateY(-18px);
    pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
    .mnq-landing-reserve-btn {
        transition: opacity 0.3s ease-in-out;
    }

    .mnq-landing-reserve-btn.is-hidden-on-scroll {
        transform: none;
    }
}
